// Sprite for a weapon store item. Returns null for non-weapons (armor/consumables share
// sort_order ranges with the weapon folders, so we must gate on item_type) or unknowns.
export function weaponSprite(item: { item_type?: string; sort_order?: number } | null | undefined): any | null {
  if (!item || item.item_type !== 'weapon' || item.sort_order == null) return null;
  return ART[item.sort_order - 10] ?? null;
}
